SELECT json_object('obs','heading','declined',CASE WHEN (SELECT b.block_id FROM headings h JOIN blocks b ON b.block_id=h.block_id WHERE h.doc_id=1 AND h.ord=0) IS NULL THEN 1 ELSE 0 END,'value_kind','text','value',(SELECT b.text FROM headings h JOIN blocks b ON b.block_id=h.block_id WHERE h.doc_id=1 AND h.ord=0),'coord',json_object('format',(SELECT format FROM documents WHERE doc_id=1),'kind','heading','ordinal',0),'provenance',json_object('class',(SELECT class FROM provenance WHERE block_id=(SELECT b.block_id FROM headings h JOIN blocks b ON b.block_id=h.block_id WHERE h.doc_id=1 AND h.ord=0)),'span',(SELECT CASE WHEN span_start IS NULL THEN NULL ELSE json_array(span_start,span_end) END FROM provenance WHERE block_id=(SELECT b.block_id FROM headings h JOIN blocks b ON b.block_id=h.block_id WHERE h.doc_id=1 AND h.ord=0))),'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',NULL)